'use client';
import { PiChat } from '../pi-chat/pi-chat';
import type { PiChatProps } from '../pi-chat/pi-chat';
import type { SharedChatController } from '@hachej/boring-ui-kit/shared-chat';
import type { SharedLabels } from './shared-labels';
import { useSharedChatProps } from './use-shared-chat';
import { withChatPlugins } from '../pi-chat-plugins/chat-plugins';

export { useSharedChat, useSharedChatProps } from './use-shared-chat';
export { defaultSharedLabels } from './shared-labels';
export { frenchSharedLabels } from './shared-labels-fr';
export type { SharedLabels } from './shared-labels';
export { createSharedChat, createChannelSocket, createFakeChannelSource, channelAvatarStates, ChannelRequestError } from '@hachej/boring-ui-kit/shared-chat';
export type { ChannelSource, ChannelEvent, ChannelMessage, Member, Conversation, Card, Step, AvatarState, SharedChatController } from '@hachej/boring-ui-kit/shared-chat';

export interface SharedChatProps extends Omit<PiChatProps, 'controller'> {
  readonly controller: SharedChatController;
  readonly participantLabels?: Partial<SharedLabels>;
}
/** Optional composition. PiChat still owns the regular shell, draft, send and composer lifecycle. */
export function SharedChat({ participantLabels, ...props }: SharedChatProps) {
  const composition = useSharedChatProps(props.controller, { locale: props.locale, labels: participantLabels });
  return <PiChat {...withChatPlugins({ ...props, ...composition })} controls={<>{composition.controls}{props.controls}</>} composerChips={<>{props.composerChips}{composition.composerChips}</>} />;
}

'use client';
import { useEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react';
import type { ReactNode } from 'react';
import { UserIcon } from 'lucide-react';
import { createSharedChat } from '@hachej/boring-ui-kit/shared-chat';
import type { ChannelSource, Conversation, SharedChatController } from '@hachej/boring-ui-kit/shared-chat';
import type { PiChatProps } from '../pi-chat/pi-chat';
import type { ConversationsConfig, MentionsConfig } from '../pi-chat/config';
import { MentionPicker } from '../pi-chat-mentions/mention-menu';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { ItemContent, ItemDescription, ItemMedia, ItemTitle } from '@/components/ui/item';
import { agentTone, MemberAvatar, SharedMembers, ReplyQuote, sharedQuote } from './messages';
import { SharedTimeline } from './timeline';
import type { TimelineApi } from './timeline';
import { SharedTextProvider } from './text';
import type { SharedTextOptions } from './text';
import { defaultSharedLabels } from './shared-labels';
import { frenchSharedLabels } from './shared-labels-fr';

const subscribeNothing = () => () => {};
/** Explicit host composition through PiChat's generic transcript, composer and catalog seams. */
export function useSharedChatProps(controller: SharedChatController | undefined, options: SharedTextOptions = {}): Omit<PiChatProps, 'controller'> {
  const state = useSyncExternalStore(controller?.subscribe ?? subscribeNothing, () => controller?.getSnapshot(), () => controller?.getSnapshot());
  const api = useRef<TimelineApi | undefined>(undefined);
  const members = state?.shared.members ?? [];
  const labels = { ...(options.locale === 'fr' ? frenchSharedLabels : defaultSharedLabels), ...options.labels };
  const mentions = useMemo<MentionsConfig>(() => ({
    listLabel: labels.sharedMembers, icon: <UserIcon aria-hidden="true" />, Picker: MentionPicker,
    label: id => members.find(member => member.id === id)?.name ?? id,
    search: async query => members.filter(member => `${member.name} ${member.id}`.toLowerCase().includes(query.toLowerCase()))
      .sort((a, b) => Number(b.kind === 'agent') - Number(a.kind === 'agent')).map(member => ({ path: member.id, label: member.name })),
    render: id => <Badge variant="secondary">@{members.find(member => member.id === id)?.name ?? id}</Badge>,
    renderSent: id => {
      const member = members.find(member => member.id === id) ?? { id, name: id, kind: 'person' };
      return <span data-testid="message-mention" data-path={id} data-agent-color={agentTone(member)?.token} className={`inline-flex items-baseline gap-1 align-baseline font-medium ${agentTone(member)?.text ?? ''}`}><span aria-hidden="true"><MemberAvatar member={member} compact interactive={false} /></span><span data-testid="mention-name">{member.name}</span></span>;
    },
    renderOption: item => <><ItemMedia variant="icon"><UserIcon aria-hidden="true" /></ItemMedia><ItemContent className="min-w-0"><ItemTitle>{item.label}</ItemTitle><ItemDescription className="m-0 truncate">{item.path}</ItemDescription></ItemContent></>,
  }), [members, labels.sharedMembers]);
  const wrap = (children: ReactNode) => <SharedTextProvider {...options}>{children}</SharedTextProvider>;
  return {
    locale: options.locale,
    timeline: { count: state?.shared.messages.length ?? 0,
      render: context => controller ? wrap(<SharedTimeline controller={controller} api={api} mentions={mentions} {...context} />) : null,
      afterSend: () => api.current?.reset() },
    controls: controller ? wrap(<SharedMembers controller={controller} />) : undefined,
    mentions,
    composerHeader: controller && state?.shared.replyTo ? wrap(<ReplyQuote targetId={state.shared.replyTo} quote={sharedQuote(state.shared, state.shared.replyTo)} onReveal={id => api.current?.reveal(id)} onRemove={() => controller.setReplyTo(undefined)} />) : undefined,
    composerHasContent: Boolean(state?.shared.files.length),
    onPickFiles: files => { if (controller) controller.setFiles([...controller.getSnapshot().shared.files, ...files]); },
    composerChips: controller && wrap(state?.shared.files.map((file, index) => <Badge key={index} variant="secondary">{file.name}<Button variant="ghost" size="icon" aria-label={`Remove ${file.name}`} onClick={() => controller.setFiles(controller.getSnapshot().shared.files.filter((_, at) => at !== index))}><span aria-hidden="true">×</span></Button></Badge>)),
    renderConnectionError: error => error instanceof Error ? error.message : String(error),
  };
}

/** Owns only the adapters it creates; each adapter borrows the host source. */
export function useSharedChat(source: ChannelSource, options: SharedTextOptions = {}) {
  const [list, setList] = useState<{ source: ChannelSource; items: Conversation[] }>();
  const [selection, setSelection] = useState<{ source: ChannelSource; id: string }>();
  const [error, setError] = useState<string>();
  const items = list?.source === source ? list.items : [];
  const conversationId = selection?.source === source ? selection.id : items[0]?.id;
  const [binding, setBinding] = useState<{ source: ChannelSource; id: string; controller: SharedChatController }>();
  useEffect(() => {
    let off = false; setError(undefined);
    void source.conversations().then(items => { if (!off) setList({ source, items }); }, cause => { if (!off) setError(String(cause)); });
    return () => { off = true; };
  }, [source]);
  useEffect(() => {
    if (conversationId === undefined) return;
    const controller = createSharedChat(source, { conversationId });
    setBinding({ source, id: conversationId, controller });
    return () => { void controller.dispose(); };
  }, [source, conversationId]);
  const controller = binding?.source === source && binding.id === conversationId ? binding.controller : undefined;
  const conversations: ConversationsConfig = { items, activeId: conversationId, loading: list?.source !== source, onSelect: id => setSelection({ source, id }) };
  const chat = useSharedChatProps(controller, options);
  return { controller, conversationId, conversations, error,
    chatProps: controller ? { ...chat, controller, conversations } : undefined,
    workspaceProps: { controller, conversationId, conversations, locale: options.locale, controls: chat.controls, chat },
  };
}

'use client';

import { useEffect, useRef, useState, useSyncExternalStore } from 'react';
import type { ComponentProps, ReactNode } from 'react';
import { channelAvatarStates } from '@hachej/boring-ui-kit/shared-chat';
import type { Card as Request, ChannelMessage, SharedChatController, Member, SharedChatState } from '@hachej/boring-ui-kit/shared-chat';
import { BotIcon, CircleIcon, ReplyIcon, Trash2Icon, XIcon } from 'lucide-react';
import { Avatar, AvatarFallback, AvatarGroup, AvatarGroupCount, AvatarImage } from '@/components/ui/avatar';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardFooter, CardHeader, CardTitle } from '@/components/ui/card';
import { Drawer, DrawerContent, DrawerTitle } from '@/components/ui/drawer';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { relativeTime } from '../pi-chat/history';
import { useChatText } from './text';

// Text shares one treatment across headings and muted bubbles; only AA-qualified default palette entries colour it.
const agentTones = [
  { token: 'chart-1', icon: 'text-chart-1', text: 'text-foreground' },
  { token: 'chart-2', icon: 'text-chart-2', text: 'text-foreground dark:text-chart-2' },
  { token: 'chart-3', icon: 'text-chart-3', text: 'text-chart-3' },
  { token: 'chart-4', icon: 'text-chart-4', text: 'text-foreground' },
  { token: 'chart-5', icon: 'text-chart-5', text: 'text-foreground' },
];
export function agentTone(member: Pick<Member, 'id' | 'kind'>) {
  if (member.kind !== 'agent') return undefined;
  let hash = 0;
  for (const character of member.id) hash = (Math.imul(hash, 31) + character.charCodeAt(0)) >>> 0;
  return agentTones[hash % agentTones.length];
}

function usePhone() {
  const [phone, setPhone] = useState(() => globalThis.matchMedia?.('(max-width: 640px)').matches === true);
  useEffect(() => { const media = globalThis.matchMedia?.('(max-width: 640px)'); if (!media) return; const change = () => setPhone(media.matches); media.addEventListener('change', change); return () => media.removeEventListener('change', change); }, []);
  return phone;
}
const latestCard = (shared: SharedChatState, id: string) => shared.messages.findLast(message => message.author === id && message.card)?.card;
const memberOf = (shared: SharedChatState, id: string): Member => shared.members.find(member => member.id === id) ?? { id, name: id, kind: 'person' };
export function sharedQuote(shared: SharedChatState, id: string | undefined) {
  const message = shared.messages.find(message => message.id === id);
  return message ? { message, author: memberOf(shared, message.author) } : undefined;
}

/** Only https, `data:image/`, `blob:` and same-origin relative addresses load; anything else falls back to the initials. */
export function safeAvatarUrl(url: string | undefined): string | undefined {
  if (!url) return undefined;
  return /^(?:https:\/\/|data:image\/|blob:)/i.test(url) || /^\/(?![/\\])/.test(url) ? url : undefined;
}

export function MemberAvatar({ member, card, interactive = true, size = 'default', compact = false }: { readonly member: Member; readonly card?: Request | undefined; readonly interactive?: boolean; readonly size?: ComponentProps<typeof Avatar>['size']; readonly compact?: boolean }) {
  const { labels } = useChatText();
  const phone = usePhone();
  const [open, setOpen] = useState(false);
  useEffect(() => {
    if (!open) return;
    const close = () => setOpen(false);
    document.addEventListener('scroll', close, true);
    return () => document.removeEventListener('scroll', close, true);
  }, [open]);
  const state = member.kind === 'agent' && card?.state && Object.hasOwn(channelAvatarStates, card.state) ? channelAvatarStates[card.state] ?? 'neutral' : 'neutral';
  const tone = state === 'blocked' ? 'text-destructive' : state === 'waiting' ? 'text-muted-foreground' : 'text-primary';
  const agent = agentTone(member);
  const avatarSrc = safeAvatarUrl(member.avatarUrl);
  const avatar = <Avatar size={compact ? 'sm' : size} data-agent-color={agent?.token} data-testid="member-avatar" role="img" aria-label={member.kind === 'agent' ? `${member.name}, ${labels.sharedAgent}` : member.name} data-state={state}>
    {avatarSrc && <AvatarImage src={avatarSrc} alt={member.name} />}
    <AvatarFallback>{member.kind === 'agent' ? <BotIcon data-lucide="bot" className={`${compact ? 'size-3' : 'size-4'} ${agent?.icon ?? ''}`} aria-hidden="true" /> : member.name.replace(/[()]/g, '').split(/\s+/).slice(0, 2).map(word => word[0]).join('').toUpperCase()}</AvatarFallback>
    {state !== 'neutral' && <span data-testid="avatar-indicator" data-state={state} className={`absolute right-0 bottom-0 ${tone}`}>
      <CircleIcon className="size-2 fill-current" aria-hidden="true" />
    </span>}
  </Avatar>;
  if (member.kind !== 'agent' || !card || !interactive) return avatar;
  const trigger = <span role="button" tabIndex={0} className="inline-flex shrink-0" data-testid={`agent-avatar-${member.id}`} data-state={state} aria-label={`${member.name}: ${card.line}`}>{avatar}</span>;
  return phone
    ? <Popover open={open} onOpenChange={setOpen}><PopoverTrigger nativeButton={false} render={trigger} /><PopoverContent data-testid="agent-state-popover" side="bottom" align="start" className="max-w-[calc(100vw-1rem)]">{card.line}</PopoverContent></Popover>
    : <Tooltip><TooltipTrigger render={trigger} /><TooltipContent>{card.line}</TooltipContent></Tooltip>;
}
function MemberBadge({ member }: { readonly member: Member }) {
  const { labels } = useChatText();
  return member.kind === 'admin' ? <Badge data-testid="author-badge" variant="secondary">{labels.sharedAdmin}</Badge> : null;
}
function Dot({ value }: { readonly value: SharedChatState['status'] | Member['presence'] }) {
  return <CircleIcon aria-hidden="true" className={`size-2 fill-current ${value === 'live' || value === 'here' ? 'text-primary' : value === 'offline' ? 'text-destructive' : 'text-muted-foreground'}`} />;
}

/** Mounted in the existing bar. The source owns membership and visibility, including the admin. */
export function SharedMembers({ controller }: { readonly controller: SharedChatController }) {
  const state = useSyncExternalStore(controller.subscribe, controller.getSnapshot, controller.getSnapshot);
  const { labels } = useChatText();
  const [open, setOpen] = useState(false);
  const phone = usePhone();
  const shared = state.shared;
  if (!shared) return null;
  const name = shared.status === 'live' ? labels.live : shared.status === 'reconnecting' ? labels.reconnecting : labels.sharedOffline;
  const content = <ul data-testid="member-list" className="m-0 flex min-w-0 list-none flex-col gap-3 p-4">
    {shared.members.map(member => <li key={member.id} data-member-id={member.id} className="flex min-w-0 items-center gap-2">
      <MemberAvatar member={member} card={latestCard(shared, member.id)} /><span className="min-w-0 flex-1 truncate">{member.name}</span>
      <Badge variant="secondary">{member.role ?? member.kind}</Badge>
      <span data-testid="presence" data-presence={member.presence ?? 'away'} role="img" aria-label={member.presence === 'here' ? labels.sharedHere : labels.sharedAway}><Dot value={member.presence} /></span>
    </li>)}
  </ul>;
  const stack = <AvatarGroup>{shared.members.slice(0, phone ? 1 : 3).map(member => <MemberAvatar key={member.id} member={member} card={latestCard(shared, member.id)} interactive={false} />)}<AvatarGroupCount>{shared.members.length}</AvatarGroupCount></AvatarGroup>;
  const trigger = <Button variant="ghost" data-testid="shared-members" aria-label={labels.sharedMemberCount(shared.members.length)} aria-haspopup="dialog" aria-expanded={open}>{stack}</Button>;
  return <div className="flex shrink-0 items-center gap-2">
    <span data-testid="shared-connection-announcement" className="sr-only" aria-live="polite" aria-atomic="true">{name}</span>
    {shared.status !== 'live' && <Tooltip><TooltipTrigger render={<span tabIndex={0} data-testid="shared-status" data-status={shared.status} role="img" aria-label={name}><Dot value={shared.status} /></span>} /><TooltipContent>{name}</TooltipContent></Tooltip>}
    {phone ? <><Button variant="ghost" data-testid="shared-members" aria-label={labels.sharedMemberCount(shared.members.length)} aria-haspopup="dialog" aria-expanded={open} onClick={() => setOpen(true)}>{stack}</Button>
      {open && <Drawer open onOpenChange={setOpen} showSwipeHandle><DrawerContent className="pi-chat max-h-[80dvh]"><div className="flex shrink-0 items-center justify-between p-4"><DrawerTitle>{labels.sharedMembers}</DrawerTitle><Button variant="ghost" size="icon" data-testid="shared-members-close" aria-label={labels.close} onClick={() => setOpen(false)}><XIcon aria-hidden="true" /></Button></div><div className="min-h-0 overflow-y-auto">{content}</div></DrawerContent></Drawer>}</>
      : <Popover open={open} onOpenChange={setOpen}><PopoverTrigger render={trigger} /><PopoverContent role="dialog" aria-label={labels.sharedMembers} align="end" className="max-w-[calc(100vw-1rem)]">{content}</PopoverContent></Popover>}
  </div>;
}

export function RequestCard({ card, action }: { readonly card: Request; readonly action: (card: Request) => Promise<void> }) {
  const { labels } = useChatText();
  const [busy, setBusy] = useState(false), [error, setError] = useState<string>();
  return <Card data-testid="request-card">
    <CardHeader><CardTitle>{card.title}</CardTitle></CardHeader>
    <CardContent><p className="m-0">{card.line}</p>{card.since && <time dateTime={card.since} className="text-muted-foreground">{labels.sharedSince(relativeTime(card.since, Date.now(), labels))}</time>}{error && <p role="alert">{error}</p>}</CardContent>
    {card.action && <CardFooter><Button disabled={busy} onClick={() => { setBusy(true); setError(undefined); void action(card).catch(error => setError(error instanceof Error ? error.message : labels.actionFailedShort)).finally(() => setBusy(false)); }}>{card.action.label}</Button></CardFooter>}
  </Card>;
}

/** Both the composer chip and the timeline quote use this one parent reference. No thread or routing policy. */
export function ReplyQuote({ targetId, quote, onRemove, onReveal }: { readonly targetId: string; readonly quote: ReturnType<typeof sharedQuote>; readonly onRemove?: () => void; readonly onReveal?: ((messageId: string) => void) | undefined }) {
  const { labels } = useChatText();
  const text = quote?.message.removed ? labels.sharedRemoved : quote?.message.card?.title ?? quote?.message.text?.split(/\r?\n/)[0] ?? labels.sharedEarlierMessage;
  return <div data-testid={onRemove ? 'composer-reply' : 'message-quote'} className="flex w-full min-w-0 items-center gap-1">
    <Button variant="ghost" className="min-w-0 max-w-full justify-start" onClick={event => {
      const chat = event.currentTarget.closest('[data-boring=pi-chat]');
      const parent = [...(chat?.querySelectorAll<HTMLElement>('[data-shared-message]') ?? [])].find(element => element.dataset.sharedMessage === targetId);
      if (parent) parent.scrollIntoView({ block: 'center', behavior: 'instant' }); else onReveal?.(targetId);
    }}><ReplyIcon aria-hidden="true" /><span className="truncate text-muted-foreground">{quote ? `${quote.author.name}: ${text}` : text}</span></Button>
    {onRemove && <Tooltip><TooltipTrigger render={<Button variant="ghost" size="icon" data-testid="composer-reply-remove" aria-label={labels.sharedCancelReply} onClick={onRemove}><XIcon aria-hidden="true" /></Button>} /><TooltipContent>{labels.sharedCancelReply}</TooltipContent></Tooltip>}
  </div>;
}

/** Participant metadata surrounds the existing bubbles, Markdown, cards and tool trace. */
export function SharedMessage({ shared, children, remove, canRemove, openFile, onReply, onReveal }: {
  readonly shared: SharedItem; readonly children: ReactNode;
  readonly remove?: ((message: ChannelMessage) => Promise<void>) | undefined;
  readonly canRemove?: ((message: ChannelMessage) => boolean) | undefined;
  readonly openFile?: ((path: string) => void) | undefined;
  readonly onReply?: ((messageId: string) => void) | undefined;
  readonly onReveal?: ((messageId: string) => void) | undefined;
}) {
  const { labels } = useChatText();
  const [error, setError] = useState<string>();
  const [actionsOpen, setActionsOpen] = useState(false);
  const phone = usePhone();
  const element = useRef<HTMLDivElement>(null);
  const press = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const start = useRef<{ x: number; y: number } | undefined>(undefined);
  const cancelPress = () => { clearTimeout(press.current); start.current = undefined; };
  useEffect(() => cancelPress, []);
  useEffect(() => {
    if (!actionsOpen) return;
    const outside = (event: PointerEvent) => { if (event.target instanceof Node && !element.current?.contains(event.target)) setActionsOpen(false); };
    document.addEventListener('pointerdown', outside);
    return () => document.removeEventListener('pointerdown', outside);
  }, [actionsOpen]);
  const { message, author, first, own, lastItem } = shared;
  const replyable = Boolean(onReply && ((author.kind === 'agent' && !message.via) || message.card));
  const removable = Boolean(remove && canRemove?.(message));
  const actionable = !message.removed && (replyable || removable);
  const heading = first && !own && <div data-testid="message-author-row" className="ml-8 flex min-w-0 items-center gap-2">
    <div className="flex min-w-0 items-center gap-2">
      <span data-testid="message-author" data-agent-color={agentTone(author)?.token} className={`min-w-0 truncate text-sm ${agentTone(author)?.text ?? 'text-muted-foreground'}`}>{author.name}</span>
      {message.via && <span data-testid="message-via" className={`min-w-0 truncate text-muted-foreground${own ? '' : ' text-sm'}`}>{labels.sharedVia(message.via)}</span>}
      {!(message.via && author.kind === 'agent') && <MemberBadge member={author} />}
    </div>
  </div>;
  const body = <>
    {message.replyTo && <ReplyQuote targetId={message.replyTo} quote={shared.quote} onReveal={onReveal} />}
    {message.removed ? <p className="text-muted-foreground">{labels.sharedRemoved}</p> : children}
  </>;
  return <div ref={element} data-shared-message={message.id} className="group/shared-message relative flex min-w-0 flex-col gap-1"
    tabIndex={phone && actionable ? 0 : undefined} aria-keyshortcuts={phone && actionable ? 'Shift+F10' : undefined}
    onKeyDown={event => {
      if (!phone || !actionable) return;
      if (event.key === 'ContextMenu' || event.key === 'F10' && event.shiftKey) { event.preventDefault(); setActionsOpen(true); }
      if (event.key === 'Escape') { setActionsOpen(false); element.current?.focus(); }
    }}
    onPointerDown={event => {
      if (!phone || !actionable || event.pointerType !== 'touch' || event.target instanceof Element && event.target.closest('button, a, input, textarea, [role=button], [role=link]')) return;
      cancelPress(); start.current = { x: event.clientX, y: event.clientY };
      press.current = setTimeout(() => setActionsOpen(true), 400);
    }}
    onPointerMove={event => { if (start.current && (Math.abs(event.clientX - start.current.x) > 8 || Math.abs(event.clientY - start.current.y) > 8)) cancelPress(); }}
    onPointerUp={cancelPress} onPointerCancel={cancelPress}
    onContextMenu={event => { if (phone && actionable && event.target instanceof Element && !event.target.closest('button, a, input, textarea, [role=button], [role=link]')) { event.preventDefault(); setActionsOpen(true); } }}>
    {heading}
    <div className="flex min-w-0 items-end gap-2">
    {!own && <div data-testid="message-avatar" className="flex w-6 shrink-0 items-end">{lastItem && <MemberAvatar member={author} card={message.via ? undefined : shared.latestCard} size="sm" />}</div>}
    <div data-testid="shared-message-content" className="flex min-w-0 flex-1 flex-col gap-1">
    {body}
    {!message.removed && message.attachments?.map(file => <Button key={file.path} variant="outline" disabled={!openFile} onClick={() => openFile?.(file.path)} className="max-w-full justify-start"><span className="truncate">{file.title ?? file.path}</span></Button>)}
    {error && <p role="alert">{error}</p>}
    </div></div>
    {actionable && <div data-testid="shared-message-actions" hidden={phone && !actionsOpen} className={`absolute right-0 top-0 ${phone && !actionsOpen ? 'hidden' : 'flex'} items-center gap-1${phone ? '' : ' opacity-0 group-hover/shared-message:opacity-100 group-focus-within/shared-message:opacity-100'}`}>
      {replyable && onReply && <Tooltip><TooltipTrigger render={<Button variant="ghost" size={phone ? 'icon' : 'icon-xs'} data-testid="shared-reply" aria-label={labels.sharedReply} onClick={() => { setActionsOpen(false); onReply(message.id); }}><ReplyIcon aria-hidden="true" /></Button>} /><TooltipContent>{labels.sharedReply}</TooltipContent></Tooltip>}
      {removable && remove && <Tooltip><TooltipTrigger render={<Button variant="ghost" size={phone ? 'icon' : 'icon-xs'} aria-label={labels.delete} onClick={() => { void remove(message).catch(error => setError(error instanceof Error ? error.message : labels.actionFailedShort)); }}><Trash2Icon aria-hidden="true" /></Button>} /><TooltipContent>{labels.delete}</TooltipContent></Tooltip>}
    </div>}
  </div>;
}

export interface SharedItem {
  readonly key: string; readonly message: ChannelMessage; readonly author: Member; readonly own: boolean; readonly first: boolean; readonly lastItem: boolean; readonly separator: boolean;
  readonly showSpinner: boolean; readonly latestCard: Request | undefined; readonly quote: ReturnType<typeof sharedQuote>;
}
export function sharedItems(shared: SharedChatState): SharedItem[] {
  const working = new Map(shared.messages.filter(message => message.streaming).map(message => [message.author, message.id]));
  const groups: ChannelMessage[][] = [];
  for (const message of shared.messages) {
    const group = groups.at(-1), previous = group?.at(-1);
    const elapsed = previous ? Date.parse(message.at) - Date.parse(previous.at) : NaN;
    if (group && previous?.author === message.author && previous.via === message.via && elapsed >= 0 && elapsed <= 15 * 60_000) group.push(message);
    else groups.push([message]);
  }
  return groups.flatMap((group, groupIndex) => {
    const lastItem = group.at(-1);
    return group.map((message, index): SharedItem => {
      const previous = index > 0 ? group[index - 1] : groups[groupIndex - 1]?.at(-1);
      return { key: `shared:${message.id}`, message, author: memberOf(shared, message.author), own: message.author === shared.me.id,
        first: index === 0, lastItem: message === lastItem,
        separator: !previous || Date.parse(message.at) - Date.parse(previous.at) > 15 * 60_000,
        showSpinner: working.get(message.author) === message.id, latestCard: latestCard(shared, message.author), quote: sharedQuote(shared, message.replyTo) };
    });
  });
}

'use client';
import { Children, useEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react';
import type { ReactNode, RefObject } from 'react';
import type { SharedChatController } from '@hachej/boring-ui-kit/shared-chat';
import type { MentionsConfig } from '../pi-chat/config';
import { MessageText } from '../pi-chat/message';
import { Markdown } from '../pi-chat-markdown/markdown';
import { useTranscript } from '../pi-chat/session';
import { TranscriptHistory } from '../pi-chat/history';
import { Message, MessageContent } from '@/components/ui/message';
import { Bubble, BubbleContent } from '@/components/ui/bubble';
import { MessageScroller, MessageScrollerViewport, MessageScrollerContent, MessageScrollerItem, MessageScrollerButton } from '@/components/ui/message-scroller';
import { SharedMessage, RequestCard, sharedItems } from './messages';
import { HostTrace } from './host-trace';
import { useChatText } from './text';

export interface TimelineApi { readonly reset: () => void; readonly reveal: (id: string) => void }
export function SharedTimeline({ controller, api, focusComposer, openFile, mentions, pendingVoice }: {
  readonly controller: SharedChatController; readonly api: RefObject<TimelineApi | undefined>;
  readonly focusComposer: () => void; readonly openFile?: ((path: string) => void) | undefined; readonly mentions: MentionsConfig; readonly pendingVoice?: ReactNode;
}) {
  const state = useSyncExternalStore(controller.subscribe, controller.getSnapshot, controller.getSnapshot);
  const { labels, icons } = useChatText();
  const items = useMemo(() => sharedItems(state.shared), [state.shared]);
  const connected = state.connection.kind === 'connected';
  const transcript = useTranscript(items, 60, 40, { state: state.history, connected: !state.disposed && connected, load: controller.loadEarlier });
  const { stick, hidden } = transcript;
  const root = useRef<HTMLDivElement>(null);
  const [revealing, setRevealing] = useState<string>();
  useEffect(() => {
    const value = { reset: () => { transcript.reset(); void stick.scrollToBottom('instant'); }, reveal: setRevealing };
    api.current = value;
    return () => { if (api.current === value) api.current = undefined; };
  });
  useEffect(() => {
    if (!revealing) return;
    const key = `shared:${revealing}`;
    if (items.some(item => item.key === key)) {
      transcript.revealTo(key);
      const frame = requestAnimationFrame(() => {
        const parent = [...(root.current?.querySelectorAll<HTMLElement>('[data-shared-message]') ?? [])].find(element => element.dataset.sharedMessage === revealing);
        if (parent) { parent.scrollIntoView({ block: 'center', behavior: 'instant' }); setRevealing(undefined); }
      });
      return () => cancelAnimationFrame(frame);
    }
    if (state.history.kind === 'loading') return;
    if (state.history.kind === 'ready' && state.history.hasMore) void controller.loadEarlier().catch(() => setRevealing(undefined));
    else setRevealing(undefined);
  }, [revealing, items, hidden, state.history]);
  const hasContent = items.length > 0 || Children.count(pendingVoice) > 0;
  const context = { pieces: { mentions: true, skills: [], renderMention: mentions.renderSent }, openFile };
  const renderMention = (path: string, text: string) => mentions.renderSent?.(path) ?? text;
  return <MessageScroller>
    <MessageScrollerViewport ref={node => { root.current = node; stick.scrollRef(node); }} data-testid="transcript-scroll" aria-label={labels.messages} className="min-h-0 flex-1 scrollbar-thumb-border scrollbar-track-transparent">
      {items.length > 0 && (hidden > 0 || state.history.kind === 'loading' || state.history.kind === 'error' || state.history.kind === 'ready' && state.history.hasMore) && <TranscriptHistory history={state.history} connected={!state.disposed && connected} onLoad={transcript.reveal} sentinelRef={transcript.sentinelRef} hidden={hidden} loaded={transcript.loaded} />}
      <div className="mx-auto w-full max-w-[720px] px-4 pt-6 pb-8 sm:px-6">
        <MessageScrollerContent aria-label={labels.messages} aria-live="polite" data-testid="transcript" className="gap-0 [&>[data-local-voice]]:mt-6">
          {transcript.visible(items).map((item, index) => {
            const { message, author, own } = item;
            const person = own || author.kind !== 'agent' || message.via !== undefined;
            return <MessageScrollerItem key={item.key} messageId={item.key} className={`[content-visibility:visible]${index > 0 ? item.first ? ' mt-6' : ' mt-2' : ''}`}>
              {item.separator && <div data-testid="time-separator" className="mb-6 flex justify-center text-xs text-muted-foreground"><time dateTime={message.at}>{labels.sharedTimestamp(message.at)}</time></div>}
              <SharedMessage shared={item} remove={controller.remove} canRemove={controller.canRemove} openFile={openFile} onReply={id => { controller.setReplyTo(id); focusComposer(); }} onReveal={setRevealing}>
                {message.card ? <article data-row-id={item.key} data-role="event" className="max-w-[80%]"><RequestCard card={message.card} action={controller.action} /></article>
                  : <article data-row-id={item.key} data-role={person ? 'user' : 'assistant'} data-streaming={message.streaming ? 'true' : undefined} className="group/message"><Message align={own ? 'end' : 'start'}><MessageContent>
                    {own ? <MessageText text={message.text ?? ''} context={context} /> : <Bubble variant="muted"><BubbleContent>
                      {message.text && <Markdown text={message.text} streaming={Boolean(message.streaming)} renderMention={renderMention} />}
                      {!message.via && author.kind === 'agent' && (message.streaming || message.steps?.length) && <HostTrace participant={author.name} steps={message.steps ?? []} streaming={Boolean(message.streaming)} active={item.showSpinner} />}
                    </BubbleContent></Bubble>}
                  </MessageContent></Message></article>}
              </SharedMessage>
            </MessageScrollerItem>;
          })}
          {pendingVoice}
        </MessageScrollerContent>
      </div>
    </MessageScrollerViewport>
    {hasContent && <div data-testid="transcript-navigation" className="flex h-12 shrink-0 items-center justify-center">{!stick.isAtBottom && <MessageScrollerButton className="static inset-auto translate-x-0" data-testid="jump-latest" aria-label={labels.jumpToLatest} title={labels.jumpToLatest} onClick={() => api.current?.reset()}><icons.jumpToLatest aria-hidden="true" /></MessageScrollerButton>}</div>}
  </MessageScroller>;
}

'use client';
import { useEffect, useState } from 'react';
import { AlertCircleIcon, CheckIcon, WrenchIcon } from 'lucide-react';
import type { Step } from '@hachej/boring-ui-kit/shared-chat';
import { Spinner } from '@/components/ui/spinner';
import { Trace, TraceCollapsible, TraceCollapsibleContent, TraceCollapsibleTrigger, TraceIcon, TraceLine, TraceTitle } from '@/components/ui/trace';
import { useChatText } from './text';

/** Host observations only. This trace neither creates Pi tool calls nor runs work. */
export function HostTrace({ steps, participant, streaming, active }: { readonly steps: readonly Step[]; readonly participant: string; readonly streaming: boolean; readonly active: boolean }) {
  const { labels } = useChatText();
  const [chosen, setChosen] = useState<boolean | undefined>();
  useEffect(() => setChosen(undefined), [participant, streaming]);
  const open = chosen ?? false;
  const state = streaming ? 'running' : steps.some(step => step.status === 'failed') ? 'failed' : 'done';
  const running = steps.reduce((found, step, index) => found === -1 && step.status === 'running' ? index : found, -1);
  const current = steps[running];
  const progress = current ? ` · ${current.label} (${running + 1}/${steps.length})` : '';
  const Icon = streaming ? Spinner : state === 'failed' ? AlertCircleIcon : CheckIcon;
  return <Trace data-testid="activity" data-boring="activity" data-state={state} data-open={open ? 'true' : 'false'} className="my-1.5">
    <TraceCollapsible open={open} onOpenChange={setChosen}>
      <TraceCollapsibleTrigger className="min-h-8 max-sm:min-h-11 pointer-coarse:min-h-11">
        <TraceLine {...(streaming ? { status: 'running' } : state === 'failed' ? { status: 'error' } : {})}>
          {!(open || streaming && !active) && <TraceIcon><Icon aria-hidden="true" /></TraceIcon>}
          <TraceTitle data-testid="activity-label">{streaming ? `${labels.sharedWorking(participant)}${progress}` : labels.steps(steps.length)}</TraceTitle>
        </TraceLine>
      </TraceCollapsibleTrigger>
      <TraceCollapsibleContent><Trace data-testid="activity-steps">
        {steps.map((step, index) => {
          const StepIcon = step.status === 'running' ? open && active && streaming && index === running ? Spinner : WrenchIcon : step.status === 'done' ? CheckIcon : AlertCircleIcon;
          return <div key={index} data-testid="activity-step" data-kind="host" data-status={step.status === 'done' ? 'completed' : step.status}>
            <TraceLine data-testid="host-step" {...(step.status === 'running' ? { status: 'running' } : step.status === 'failed' ? { status: 'error' } : {})}>
              <TraceIcon><StepIcon aria-hidden="true" /></TraceIcon><TraceTitle><div className="flex min-w-0 flex-col"><span>{step.label}</span>{step.detail && <pre data-testid="step-detail" className="m-0 text-xs font-mono whitespace-pre-wrap text-muted-foreground [overflow-wrap:anywhere]">{step.detail}</pre>}</div></TraceTitle>
            </TraceLine>
          </div>;
        })}
      </Trace></TraceCollapsibleContent>
    </TraceCollapsible>
  </Trace>;
}

'use client';
import { createContext, useContext, useMemo } from 'react';
import type { ReactNode } from 'react';
import { useChatText as useNativeText } from '../pi-chat/labels';
import { defaultSharedLabels } from './shared-labels';
import type { SharedLabels } from './shared-labels';
import { frenchSharedLabels } from './shared-labels-fr';

export interface SharedTextOptions { readonly locale?: 'en' | 'fr' | undefined; readonly labels?: Partial<SharedLabels> | undefined }
const Context = createContext(defaultSharedLabels);
export function SharedTextProvider({ children, locale, labels }: SharedTextOptions & { readonly children: ReactNode }) {
  const value = useMemo(() => ({ ...(locale === 'fr' ? frenchSharedLabels : defaultSharedLabels), ...labels }), [locale, labels]);
  return <Context.Provider value={value}>{children}</Context.Provider>;
}
export function useChatText() {
  const native = useNativeText(), labels = useContext(Context);
  return { ...native, labels: { ...native.labels, ...labels } };
}

export function formatTimestamp(at: string, locale: string) {
  const date = new Date(at);
  if (!Number.isFinite(date.getTime())) return at;
  return `${new Intl.DateTimeFormat(locale, { weekday: 'short', day: 'numeric', month: 'short' }).format(date)}, ${new Intl.DateTimeFormat(locale, { hour: '2-digit', minute: '2-digit' }).format(date)}`;
}
export const defaultSharedLabels = {
  sharedTimestamp: (at: string) => formatTimestamp(at, 'en'),
  sharedMembers: 'Members', sharedMemberCount: (count: number) => `${count} members`,
  sharedAgent: 'Agent', sharedVia: (name: string) => `via ${name}`,
  sharedWorking: (name: string) => `${name} is working…`,
  sharedReply: 'Reply', sharedCancelReply: 'Cancel reply', sharedEarlierMessage: 'Earlier message',
  sharedAdmin: 'Admin', sharedHere: 'Here', sharedAway: 'Away', sharedOffline: 'Offline',
  sharedRemoved: 'Message removed', sharedSince: (time: string) => `Since ${time}`,
};
export type SharedLabels = typeof defaultSharedLabels;

import type { SharedLabels } from './shared-labels';
import { formatTimestamp } from './shared-labels';
export const frenchSharedLabels: SharedLabels = {
  sharedTimestamp: (at: string) => formatTimestamp(at, 'fr'),
  sharedMembers: 'Membres', sharedMemberCount: (count: number) => `${count} membres`,
  sharedAgent: 'Agent', sharedVia: (name: string) => `via ${name}`,
  sharedWorking: (name: string) => `${name} travaille…`,
  sharedReply: 'Répondre', sharedCancelReply: 'Annuler la réponse', sharedEarlierMessage: 'Message précédent',
  sharedAdmin: 'Admin', sharedHere: 'Présent', sharedAway: 'Absent', sharedOffline: 'Hors ligne',
  sharedRemoved: 'Message supprimé', sharedSince: (time: string) => `Depuis ${time}`,
};
